#define LITSIZE 4

int cc[1000000];
unsigned char output[1000000];
int output_len = 0;
long low = 0;
long range = 1;

void normalize() {
    while (range < RADIX) {
        int byte_val = (low / RADIX) + 1;
        if (byte_val > 255) byte_val = 255;
