    warn "Total operations: " . scalar(@operations) . "\n";

    my $encoder = ArithmeticEncoder->new();
    warn "Encoding operation count: " . scalar(@operations) . "\n";
    $encoder->put_integer(scalar @operations, 9, 0);

    foreach my $op (@operations) {
        if ($op->[0] eq 'ref') {
            $encoder->put_bit(1, 1);
            $encoder->put_integer($op->[1], 5, 2);
            $encoder->put_integer($op->[2], 2, 3);
        } else {
            $encoder->put_bit(0, 1);
            my $char_val = $op->[1];
            if ($char_val < 0) {
